import requests
import json
from markdown_it import MarkdownIt
from mineru.cli.markdown_parser import MarkdownTranslationLogic, SimpleMarkdownRenderer

class LLaMACppTranslator:
    """
    负责调用 LLaMA.cpp HTTP API 进行翻译的核心类
    """
    
    def __init__(self, api_url="http://127.0.0.1:8080", timeout=60):
        self.api_url = api_url
        self.timeout = timeout

    def translate(self, text):
        """
        发送文本到 LLM 进行翻译
        """
        if not text or not text.strip():
            return text

        # 提示词模板
        prompt_template = """你是一个专业的学术和技术文档翻译专家。请将以下Markdown格式的文本翻译为简体中文：

要求：
1. **严格保留Markdown格式**：不要修改任何加粗(**)、斜体(*)、链接([...](...))、图片(![...](...))、代码块(```)等标记符号。
2. **严禁修改链接和图片路径**：括号 `()` 内的路径必须原样保留，不得翻译或将括号改为中文全角括号。
3. **保留LaTeX公式和占位符**：严禁修改或翻译任何由 `$` 或 `$$` 包围的内容，以及形如 `MATH_FIXED_11X` 的占位符，保持其原样输出。
4. **上下文连贯**：确保翻译后的句子通顺、符合中文表达习惯，不要逐字翻译。
5. **术语准确**：准确翻译专业术语。
6. **只输出译文**：不要包含任何解释性文字或前缀后缀。
7. **禁止增加格式**：不要增加原文中不存在的Markdown格式（如加粗、标题等），只翻译文本内容。

待翻译文本：
{text}

翻译结果："""

        prompt = prompt_template.format(text=text)

        payload = {
            "prompt": prompt,
            "stream": False,
            "temperature": 0.1,
            "top_p": 0.9,
            "top_k": 40,
            "n_predict": len(text) * 2,
            "stop": ["\n\n", "待翻译文本：", "翻译结果："]
        }

        try:
            response = requests.post(
                f"{self.api_url}/completion", 
                json=payload, 
                timeout=self.timeout
            )
            response.raise_for_status()
            
            result = response.json()
            translated_text = result.get("content", "").strip()
            
            # 清理可能的重复内容
            if "翻译结果：" in translated_text:
                translated_text = translated_text.split("翻译结果：")[-1].strip()
            
            return translated_text if translated_text else text
            
        except Exception as e:
            print(f"翻译处理失败: {e}")
            return text # 失败时返回原文



def translate_markdown_file(input_path, output_path, api_url):
    try:
        with open(input_path, 'r', encoding='utf-8') as f:
            content = f.read()
            
        translator = LLaMACppTranslator(api_url=api_url)
        logic = MarkdownTranslationLogic()
        
        # 核心翻译逻辑：解析、提取、翻译并返回重构后的字符串
        new_content = logic.translate_markdown_content(content, translator)
        
        with open(output_path, 'w', encoding='utf-8') as f:
            f.write(new_content)
            
        return True
    except Exception as e:
        print(f"Error during translation: {e}")
        return False
